// ============================================================
// TRANSFORMATION: Configuration rows → Global variables object
// ============================================================
// Reads all rows from the 'Configuration' sheet (Clé / Valeur)
// and builds a single config object accessible downstream.
//
// Expected sheet structure:
// | Clé              | Valeur                          |
// |------------------|---------------------------------|
// | COMPANY_NAME     | Mon Entreprise                  |
// | SYSTEM_PROMPT    | Tu es un assistant IA...        |
// | FIELD_1_NAME     | Nom complet                     |
// | FIELD_2_NAME     | Organisation / Objectif         |
// | FIELD_3_NAME     | Volume / Budget                 |
// | FIELD_4_NAME     | Matériau / Préférences          |
// ============================================================

const configRows = $input.all();
const config = {};
const fieldNames = {};

for (const row of configRows) {
  const key = (row.json['Clé'] || row.json['Cle'] || row.json['cle'] || row.json['clé'] || row.json['Key'] || row.json['key'] || '').toString().trim();
  const value = (row.json['Valeur'] || row.json['valeur'] || row.json['Value'] || row.json['value'] || '').toString().trim();

  if (key) {
    config[key] = value;

    // Extract field names for dynamic mapping
    const fieldMatch = key.match(/^FIELD_(\d+)_NAME$/);
    if (fieldMatch) {
      fieldNames[`field_${fieldMatch[1]}`] = value;
    }
  }
}

// Validate required keys
const requiredKeys = ['COMPANY_NAME', 'SYSTEM_PROMPT'];
const missingKeys = requiredKeys.filter(k => !config[k]);
if (missingKeys.length > 0) {
  throw new Error(`❌ Configuration incomplète. Clés manquantes: ${missingKeys.join(', ')}`);
}

return [{
  json: {
    config: config,
    fieldNames: fieldNames,
    companyName: config.COMPANY_NAME,
    systemPrompt: config.SYSTEM_PROMPT,
    field1: config.FIELD_1_NAME || 'Nom complet',
    field2: config.FIELD_2_NAME || 'Information 2',
    field3: config.FIELD_3_NAME || 'Information 3',
    field4: config.FIELD_4_NAME || 'Information 4',
    _meta: {
      configLoadedAt: new Date().toISOString(),
      totalKeys: Object.keys(config).length,
      totalFields: Object.keys(fieldNames).length
    }
  }
}];

// ============================================================
// AGNOSTIC CATALOG FORMATTER
// ============================================================
// Ce code est 100% agnostique : il lit TOUTES les colonnes
// présentes dans l'onglet 'Catalogue', quel que soit leur nom.
// Fonctionne pour : vêtements, repas, immobilier, services, etc.
//
// Exemple de sortie :
// --- Produit 1 ---
// Nom: T-Shirt Bio
// Prix: 29.99€
// Taille: M, L, XL
// ---
// ============================================================

const catalogRows = $input.all();

if (!catalogRows || catalogRows.length === 0) {
  return [{ json: { catalog_text: '⚠️ Le catalogue est vide. Aucun produit ou service trouvé.' } }];
}

// Detect all column names from the first row
const sampleRow = catalogRows[0].json;
const columnNames = Object.keys(sampleRow).filter(key => {
  // Filter out n8n internal metadata keys
  const lower = key.toLowerCase();
  return !lower.startsWith('_') && 
         lower !== 'row_number' && 
         lower !== 'row number' &&
         key !== '';
});

if (columnNames.length === 0) {
  return [{ json: { catalog_text: '⚠️ Aucune colonne détectée dans le catalogue.' } }];
}

// Format each row as a readable text block
const formattedItems = catalogRows.map((row, index) => {
  const data = row.json;
  const lines = [`--- Élément ${index + 1} ---`];

  for (const col of columnNames) {
    const value = data[col];

    // Skip empty or null values
    if (value === null || value === undefined || value === '') continue;

    // Capitalize the column name for readability
    const displayName = col
      .replace(/_/g, ' ')
      .replace(/\b\w/g, char => char.toUpperCase());

    lines.push(`${displayName}: ${value}`);
  }

  return lines.join('\n');
}).filter(block => block.split('\n').length > 1); // Remove items with no data

const catalogText = formattedItems.length > 0
  ? `📋 CATALOGUE (${formattedItems.length} éléments):\n\n${formattedItems.join('\n\n')}`
  : '⚠️ Aucun élément valide trouvé dans le catalogue.';

// Also provide structured data for advanced use
const structuredData = catalogRows.map(row => {
  const clean = {};
  for (const col of columnNames) {
    if (row.json[col] !== null && row.json[col] !== undefined && row.json[col] !== '') {
      clean[col] = row.json[col];
    }
  }
  return clean;
}).filter(obj => Object.keys(obj).length > 0);

return [{
  json: {
    catalog_text: catalogText,
    total_items: formattedItems.length,
    columns_detected: columnNames,
    structured_data: structuredData,
    _meta: {
      generatedAt: new Date().toISOString(),
      columnsCount: columnNames.length,
      rowsProcessed: catalogRows.length
    }
  }
}];

// ============================================================
// DYNAMIC LEAD NORMALIZER
// ============================================================
// Ce nœud reçoit les données de l'Agent (clés génériques) +
// la configuration du client, et mappe dynamiquement les
// valeurs vers les bonnes colonnes du Sheet 'Leads'.
//
// Données reçues de l'Agent via le Tool :
// - nom_contact  → mappé vers FIELD_1_NAME (ex: 'Nom complet')
// - variable_2   → mappé vers FIELD_2_NAME (ex: 'Organisation')
// - variable_3   → mappé vers FIELD_3_NAME (ex: 'Budget')
// - variable_4   → mappé vers FIELD_4_NAME (ex: 'Préférences')
//
// Le résultat est un objet avec les VRAIS noms de colonnes
// du Sheet, prêt à être inséré directement.
// ============================================================

// Get the trigger input data (from the Agent tool call)
const triggerData = $('Execute Workflow Trigger').item.json;

// Get config rows to build field name mapping
const configRows = $input.all();
const config = {};

for (const row of configRows) {
  const key = (row.json['Clé'] || row.json['Cle'] || row.json['cle'] || row.json['clé'] || row.json['Key'] || row.json['key'] || '').toString().trim();
  const value = (row.json['Valeur'] || row.json['valeur'] || row.json['Value'] || row.json['value'] || '').toString().trim();
  if (key) config[key] = value;
}

// Build the dynamic column mapping
const fieldMapping = {
  'nom_contact': config.FIELD_1_NAME || 'Nom complet',
  'variable_2':  config.FIELD_2_NAME || 'Information 2',
  'variable_3':  config.FIELD_3_NAME || 'Information 3',
  'variable_4':  config.FIELD_4_NAME || 'Information 4'
};

// Build the output row with the REAL column names from the client's sheet
const leadRow = {};

// Map each generic key to the real column name
for (const [genericKey, realColumnName] of Object.entries(fieldMapping)) {
  const value = triggerData[genericKey];
  if (value !== undefined && value !== null && value !== '') {
    leadRow[realColumnName] = value.toString().trim();
  }
}

// Add metadata columns (always present)
leadRow['Date'] = new Date().toLocaleDateString('fr-FR', {
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit'
});
leadRow['Source'] = 'AI Chat Agent';
leadRow['Statut'] = 'Nouveau';

// Also pass through any EXTRA fields the agent might have collected
// that don't match the standard generic keys
const standardKeys = ['nom_contact', 'variable_2', 'variable_3', 'variable_4', 'query'];
for (const [key, value] of Object.entries(triggerData)) {
  if (!standardKeys.includes(key) && value && value.toString().trim()) {
    // Check if there's a matching FIELD_N_NAME for extra fields
    const extraFieldMatch = key.match(/^variable_(\d+)$/);
    if (extraFieldMatch) {
      const fieldNum = extraFieldMatch[1];
      const configKey = `FIELD_${fieldNum}_NAME`;
      if (config[configKey]) {
        leadRow[config[configKey]] = value.toString().trim();
      }
    } else {
      // Pass through as-is (for any custom fields)
      leadRow[key] = value.toString().trim();
    }
  }
}

return [{
  json: {
    leadRow: leadRow,
    fieldMapping: fieldMapping,
    _meta: {
      normalizedAt: new Date().toISOString(),
      fieldsPopulated: Object.keys(leadRow).length,
      companyName: config.COMPANY_NAME || 'Unknown'
    }
  }
}];

// ============================================================
// PREPARE DATA FOR GOOGLE SHEETS APPEND
// ============================================================
// Extracts the leadRow object and flattens it so Google Sheets
// can auto-map each key to its corresponding column header.
// ============================================================

const leadRow = $input.item.json.leadRow;

if (!leadRow || Object.keys(leadRow).length === 0) {
  throw new Error('❌ Aucune donnée de lead à écrire.');
}

// Flatten: return the leadRow directly as the output JSON
// This allows Google Sheets to auto-map columns by name
return [{ json: leadRow }];

// Return success confirmation to the Agent
return [{
  json: {
    success: true,
    message: `✅ Lead enregistré avec succès dans le Google Sheet.`,
    timestamp: new Date().toISOString()
  }
}];
